describe('Email Uniqueness Validation - Registration', () => {
  beforeEach(() => {
    cy.visit('/register');
  });

  it('should display error when trying to register with an already-used email', () => {
    // Setup: Register with a valid email
    cy.get('[data-testid="email-input"]').type('testuser@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123!');
    cy.get('[data-testid="confirm-password-input"]').type('SecurePassword123!');
    cy.get('[data-testid="register-button"]').click();

    // Intercept the registration API call
    cy.intercept('POST', '/api/auth/register').as('registerRequest');

    // Verify error message appears
    cy.wait('@registerRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
    });

    // Verify error message is visible
    cy.get('[data-testid="email-error-message"]').should('be.visible');
    cy.get('[data-testid="email-error-message"]').should('contain', 'Email already in use');

    // Verify form is still visible
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');
    cy.get('[data-testid="confirm-password-input"]').should('be.visible');
    cy.get('[data-testid="register-button"]').should('be.visible');
  });

  it('should not display error when registering with a new email', () => {
    // Setup: Register with a new, valid email
    cy.get('[data-testid="email-input"]').type('newuser@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123!');
    cy.get('[data-testid="confirm-password-input"]').type('SecurePassword123!');
    cy.get('[data-testid="register-button"]').click();

    // Intercept the registration API call
    cy.intercept('POST', '/api/auth/register').as('registerRequest');

    // Verify success message appears
    cy.wait('@registerRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify success message is visible
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Registration successful');

    // Verify form is cleared
    cy.get('[data-testid="email-input"]').should('have.value', '');
    cy.get('[data-testid="password-input"]').should('have.value', '');
    cy.get('[data-testid="confirm-password-input"]').should('have.value', '');
    cy.get('[data-testid="register-button"]').should('be.disabled');
  });
});
